import Redis from 'ioredis';
const redis = new Redis();

async function warmProductCache() {
  const hotProducts = await db.product.findMany({
    where: { isHot: true },
    select: { id: true, name: true, price: true }
  });

  const pipeline = redis.pipeline();
  for (const product of hotProducts) {
    pipeline.setex(
      `product:${product.id}:details`,
      600,
      JSON.stringify(product)
    );
  }

  await pipeline.exec();
  console.log(`Warmed ${hotProducts.length} product keys`);
}

public class CacheWarmingService : BackgroundService
{
    private readonly IServiceProvider _services;
    private readonly IConnectionMultiplexer _redis;

    public CacheWarmingService(IServiceProvider services, IConnectionMultiplexer redis)
    {
        _services = services;
        _redis = redis;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        await WarmFeatureFlagsAsync(stoppingToken);
        await WarmCountriesAsync(stoppingToken);
    }

    private async Task WarmFeatureFlagsAsync(CancellationToken ct)
    {
        using var scope = _services.CreateScope();
        var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
        var redisDb = _redis.GetDatabase();

        var flags = await db.FeatureFlags.ToListAsync(ct);
        var pipe = redisDb.CreateBatch();

        foreach (var flag in flags)
        {
            pipe.StringSetAsync(
                $"feature:flag:{flag.Name}",
                JsonSerializer.Serialize(flag),
                TimeSpan.FromHours(1)
            );
        }

        await pipe.ExecuteAsync(ct);
    }
}
